def canonical_record_payload(record: Mapping[str, object]) -> bytes:
    """Canonical bytes for one framed record, fast where equality is proven."""

    if is_fast_canonical_safe(record):
        return json.dumps(
            record,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
    return canonical_json_bytes(record)

