def _storage_root(path: Path) -> Path:
    path = Path(path)
    if path.is_symlink():
        raise IntegrityError(f"storage root must not be a symlink: {path}")
    path.mkdir(parents=True, exist_ok=True)
    if path.is_symlink():
        raise IntegrityError(f"storage root must not be a symlink: {path}")
    return path.resolve(strict=True)

