def _verified_root(self, reference: LayerRef) -> tuple[dict[str, Any], RecordSchema, PartitionPolicy]:
    root = self._load_root(reference)
    expected_root = {
        "format",
        "formatVersion",
        "layerId",
        "layerKind",
        "schema",
        "profileId",
        "partitionPolicy",
        "members",
        "recordCount",
    }
    if (
        set(root) != expected_root
        or root["format"] != "docspec-record-layer"
