            (self.comment_input, _COMMENT_SCOPE, _COMMENT_SCHEMA),
            (
                self.federal_register_input,
                _FEDERAL_REGISTER_SCOPE,
                _FEDERAL_REGISTER_SCHEMA,
            ),
        )
        for selector, scope_id, schema_name in expected:
            if selector is not None and (
