def summarize_store_tasks(tasks: Iterable[StoreTask]) -> tuple[int, str]:
    """Digest a task stream without retaining its members."""

    count = 0

    def rows() -> Iterable[dict[str, Any]]:
        nonlocal count
        for task in tasks:
            count += 1
            yield task.to_dict()

    digest = ordered_json_sequence_digest(rows())
    return count, digest

