def ordered_json_sequence_digest(values: Iterable[Any]) -> str:
    """Digest a canonical JSON array without retaining all items in memory."""

    digest = OrderedJsonSequenceDigester()
    for value in values:
        digest.accept(value)
    return digest.finish()

