    exact_join_result = {
        "type": "object",
        "additionalProperties": False,
        "required": ["joins"],
        "properties": {
            "joins": {
                "type": "array",
                "items": exact_join,
                "uniqueItems": True,
            }
        },
    }
    sampling_result = {
        "type": "object",
        "additionalProperties": False,
        "required": [
            "frameAdmitted",
            "partition",
            "stratum",
            "orderHash",
            "rank",
            "stratumSize",
            "allocationMethod",
            "limit",
            "drawn",
        ],
        "properties": {
            "frameAdmitted": {"type": "boolean"},
            "partition": nullable_text,
            "stratum": {"type": "array", "items": text},
            "orderHash": {
                "anyOf": [
                    {"type": "null"},
                    {"type": "string", "pattern": "^[0-9a-f]{32}$"},
                ]
            },
            "rank": {"anyOf": [{"type": "null"}, {"type": "integer", "minimum": 1}]},
            "stratumSize": {
                "anyOf": [{"type": "null"}, {"type": "integer", "minimum": 1}]
            },
            "allocationMethod": {"enum": ["all", "rank-over-sqrt-stratum-size"]},
            "limit": {"anyOf": [{"type": "null"}, {"type": "integer", "minimum": 1}]},
            "drawn": {"type": "boolean"},
        },
    }
    selection_decision = {
        "type": "object",
        "additionalProperties": False,
        "required": ["decisionId", "outcome", "disposition", "reasonCode", "reason"],
        "properties": {
            "decisionId": text,
            "outcome": {"enum": ["pass", "fail"]},
            "disposition": {
                "anyOf": [
                    {"type": "null"},
                    {"enum": [
                        CatalogDisposition.EXCLUDED.value,
                        CatalogDisposition.DELETED.value,
                        CatalogDisposition.UNAVAILABLE.value,
                        CatalogDisposition.FAILED.value,
                    ]},
                ]
            },
            "reasonCode": nullable_text,
            "reason": nullable_text,
        },
        "oneOf": [
            {
                "properties": {
                    "outcome": {"const": "pass"},
                    "disposition": {"type": "null"},
                    "reasonCode": {"type": "null"},
                    "reason": {"type": "null"},
                }
            },
            {
                "properties": {
                    "outcome": {"const": "fail"},
                    "disposition": {
                        "enum": [
                            CatalogDisposition.EXCLUDED.value,
                            CatalogDisposition.DELETED.value,
                            CatalogDisposition.UNAVAILABLE.value,
                            CatalogDisposition.FAILED.value,
                        ]
                    },
                    "reasonCode": text,
                    "reason": text,
                }
            },
        ],
    }
    selection_result = {
        "type": "object",
        "additionalProperties": False,
        "required": ["decisions", "finalDisposition", "reasonCode", "reason"],
        "properties": {
            "decisions": {
                "type": "array",
                "items": selection_decision,
                "minItems": 1,
                "uniqueItems": True,
            },
            "finalDisposition": {"enum": [value.value for value in CatalogDisposition]},
            "reasonCode": nullable_text,
            "reason": nullable_text,
        },
    }
    item = {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": SOURCE_CATALOG_ITEM_SCHEMA_ID,
        "type": "object",
        "additionalProperties": False,
        "required": [
            "sourceItemId",
            "documentId",
            "sourceIssuedVersion",
            "sourceNativeFacts",
            "normalizedMetadata",
            "sourceObservedTopics",
            "sourceObservations",
            "interpretations",
            "candidateRenditions",
            "selection",
        ],
        "properties": {
            "sourceItemId": {"type": "string", "minLength": 1},
            "documentId": {"type": "string", "minLength": 1},
            "sourceIssuedVersion": {"type": "string", "minLength": 1},
            "sourceNativeFacts": {
                "type": "array",
                "items": source_native_fact,
                "minItems": 1,
                "uniqueItems": True,
            },
            "normalizedMetadata": normalized_metadata,
            "sourceObservedTopics": {"type": "array", "items": observed_topic, "uniqueItems": True},
            "sourceObservations": {"type": "array", "items": source_observation, "uniqueItems": True},
            "interpretations": {
                "type": "array",
                "items": {
                    "oneOf": [
                        interpretation("normalization", normalization_result),
                        interpretation("rendition-preference", rendition_result),
                        interpretation("sampling", sampling_result),
                        interpretation("selection", selection_result),
                        interpretation("exact-join", exact_join_result),
                        interpretation("topic-recovery", topic_recovery_result),
                    ]
                },
                "minItems": 1,
                "uniqueItems": True,
                "allOf": [
                    {
                        "contains": {
                            "type": "object",
                            "required": ["interpretationKind"],
                            "properties": {"interpretationKind": {"const": kind}},
                        },
                        "minContains": 1,
                        "maxContains": 1,
                    }
                    for kind in (
                        "exact-join",
                        "normalization",
                        "rendition-preference",
                        "sampling",
                        "selection",
                        "topic-recovery",
                    )
                ],
            },
            "candidateRenditions": {"type": "array", "items": candidate},
            "selection": selection,
        },
    }
    policy = {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": SOURCE_CATALOG_POLICY_SCHEMA_ID,
        "type": "object",
        "additionalProperties": False,
        "required": ["format", "formatVersion", "policyId", "policyVersion", "configuration"],
        "properties": {
            "format": {"const": "docspec-catalog-policy"},
            "formatVersion": {"const": "1.0"},
            "policyId": {"type": "string", "minLength": 1},
            "policyVersion": {"type": "string", "minLength": 1},
            # The wrapper is generic. Each injected policy owns and closes its
            # configuration before the builder receives it.
            "configuration": {"type": "object"},
        },
    }
    receipt = {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": SOURCE_CATALOG_RECEIPT_SCHEMA_ID,
        "type": "object",
        "additionalProperties": False,
        "required": [
            "format",
            "formatVersion",
            "catalogId",
            "catalogSchemaDigest",
            "sourceSystemSetDigest",
            "sourceNativeSchemaSetDigest",
            "selectionPolicyId",
            "selectionPolicyVersion",
            "selectionPolicyDigest",
            "sourceNativeInputs",
            "catalogStateDigest",
            "requestedUniverseSetDigest",
            "selectedSourceSetDigest",
            "itemCount",
            "dispositionCounts",
            "partitionPolicy",
            "partitions",
            "joinCoverage",
            "normalizedFieldsDigest",
            "joinedFieldsDigest",
            "dispositionsDigest",
            "reasonsDigest",
            "interpretationsDigest",
            "renditionChoicesDigest",
            "byteMeasurements",
            "verifierId",
            "verifierVersion",
            "verifierImplementationId",
            "semanticVerdict",
        ],
        "properties": {
            "format": {"const": "docspec-source-catalog-build-receipt"},
            "formatVersion": {"const": "1.0"},
            "catalogId": {"type": "string", "minLength": 1},
            "catalogSchemaDigest": digest,
            "sourceSystemSetDigest": digest,
            "sourceNativeSchemaSetDigest": digest,
            "selectionPolicyId": text,
            "selectionPolicyVersion": text,
            "selectionPolicyDigest": digest,
            "sourceNativeInputs": {
                "type": "array",
                "minItems": 1,
                "uniqueItems": True,
                "items": {
                    "type": "object",
                    "additionalProperties": False,
                    "required": ["logicalId", "artifactDigest"],
                    "properties": {"logicalId": text, "artifactDigest": digest},
                },
            },
            "catalogStateDigest": digest,
            "requestedUniverseSetDigest": digest,
            "selectedSourceSetDigest": digest,
            "itemCount": {"type": "integer", "minimum": 0},
            "dispositionCounts": {
                "type": "object",
                "additionalProperties": False,
                "required": [value.value for value in CatalogDisposition],
                "properties": {
                    value.value: {"type": "integer", "minimum": 0} for value in CatalogDisposition
                },
            },
            "partitionPolicy": {
                "type": "object",
                "additionalProperties": False,
                "required": ["policyId", "policyVersion", "policyDigest", "bucketCount"],
                "properties": {
                    "policyId": text,
                    "policyVersion": text,
                    "policyDigest": digest,
                    "bucketCount": {"type": "integer", "minimum": 1, "maximum": 65536},
                },
            },
            "partitions": {
                "type": "array",
                "uniqueItems": True,
                "items": {
                    "type": "object",
                    "additionalProperties": False,
                    "required": ["partitionId", "blobRef", "byteSize", "recordCount"],
                    "properties": {
                        "partitionId": text,
                        "blobRef": digest,
                        "byteSize": {"type": "integer", "minimum": 0},
                        "recordCount": {"type": "integer", "minimum": 1},
                    },
                },
            },
            "joinCoverage": {
                "type": "array",
                "uniqueItems": True,
                "maxItems": SOURCE_CATALOG_MAX_JOIN_IDS,
                "items": {
                    "type": "object",
                    "additionalProperties": False,
                    "required": ["joinId", "eligible", "matched", "unmatched", "nullResult"],
                    "properties": {
                        "joinId": text,
                        "eligible": {"type": "integer", "minimum": 0},
                        "matched": {"type": "integer", "minimum": 0},
                        "unmatched": {"type": "integer", "minimum": 0},
                        "nullResult": {"type": "integer", "minimum": 0},
                    },
                },
            },
            "normalizedFieldsDigest": digest,
            "joinedFieldsDigest": digest,
            "dispositionsDigest": digest,
            "reasonsDigest": digest,
            "interpretationsDigest": digest,
            "renditionChoicesDigest": digest,
            "byteMeasurements": {
                "type": "object",
                "additionalProperties": False,
                "required": [
                    "payloadBytesRead",
                    "payloadBytesReused",
                    "payloadBytesWritten",
                    "publicationBytesWritten",
                ],
                "properties": {
                    "payloadBytesRead": {"type": "integer", "minimum": 0},
                    "payloadBytesReused": {"type": "integer", "minimum": 0},
                    "payloadBytesWritten": {"type": "integer", "minimum": 0},
                    "publicationBytesWritten": {"type": "integer", "minimum": 0},
                },
            },
            "verifierId": {"type": "string", "minLength": 1},
            "verifierVersion": {"type": "string", "minLength": 1},
            "verifierImplementationId": {"type": "string", "minLength": 1},
            "semanticVerdict": {"const": "pass"},
        },
    }
    return {
        "source-item.schema.json": item,
        "catalog-policy.schema.json": policy,
        "catalog-build-receipt.schema.json": receipt,
    }

