def utf8_byte_offsets(text: str) -> tuple[int, ...]:
    """Map every Python codepoint boundary to its exact UTF-8 byte offset."""

    offsets = [0]
    total = 0
    for character in text:
        total += len(character.encode("utf-8"))
        offsets.append(total)
    return tuple(offsets)

