def _quantiles(values: Sequence[str]) -> dict[str, str]:
    ordered = sorted(values, key=lambda value: value.ljust(12, "0"))
    return {
        "count": str(len(ordered)),
        "maximum": ordered[-1],
        "median": ordered[len(ordered) // 2],
        "minimum": ordered[0],
    }

